import 'dart:typed_data';

import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:image_picker/image_picker.dart';

/// Where the photo comes from.
enum PhotoOrigin { camera, gallery }

/// The bytes and metadata a picked photo hands to the upload.
///
/// [filename] is generated by the app, never reused from the gallery: a phone
/// photo name can contain a person's name, and N-02 forbids PHI in file names.
class PickedPhoto {
  const PickedPhoto({
    required this.bytes,
    required this.filename,
    required this.mimeType,
  });

  final Uint8List bytes;
  final String filename;
  final String mimeType;
}

/// The picker seam.
///
/// Widget tests override the provider with a fake so no platform channel is
/// invoked, and a cancelled pick is `null` rather than an error.
abstract interface class PhotoSource {
  Future<PickedPhoto?> pick(PhotoOrigin origin);
}

/// `image_picker` implementation.
///
/// The image is downscaled and re-encoded before it leaves the device: a
/// modern phone photo is many megabytes and the task evidence does not need
/// full resolution. This also keeps the upload under the server's 10 MiB cap.
class ImagePickerPhotoSource implements PhotoSource {
  ImagePickerPhotoSource({ImagePicker? picker})
    : _picker = picker ?? ImagePicker();

  final ImagePicker _picker;

  static const int maxDimension = 1600;
  static const int imageQuality = 80;

  static const Set<String> _acceptedMimeTypes = <String>{
    'image/jpeg',
    'image/png',
    'image/heic',
  };

  @override
  Future<PickedPhoto?> pick(PhotoOrigin origin) async {
    final XFile? file = await _picker.pickImage(
      source: origin == PhotoOrigin.camera
          ? ImageSource.camera
          : ImageSource.gallery,
      maxWidth: maxDimension.toDouble(),
      maxHeight: maxDimension.toDouble(),
      imageQuality: imageQuality,
    );

    if (file == null) {
      return null;
    }

    final Uint8List bytes = await file.readAsBytes();

    if (bytes.isEmpty) {
      return null;
    }

    final String mimeType = _mimeTypeFor(file);

    return PickedPhoto(
      bytes: bytes,
      filename: _neutralFilename(mimeType),
      mimeType: mimeType,
    );
  }

  String _mimeTypeFor(XFile file) {
    final String? declared = file.mimeType;

    if (declared != null && _acceptedMimeTypes.contains(declared)) {
      return declared;
    }

    final String name = file.name.toLowerCase();

    if (name.endsWith('.png')) {
      return 'image/png';
    }

    if (name.endsWith('.heic') || name.endsWith('.heif')) {
      return 'image/heic';
    }

    return 'image/jpeg';
  }

  /// Opaque, collision-safe name: no user filename, no health data.
  String _neutralFilename(String mimeType) {
    final String extension = switch (mimeType) {
      'image/png' => 'png',
      'image/heic' => 'heic',
      _ => 'jpg',
    };

    return 'evidence-${DateTime.now().microsecondsSinceEpoch}.$extension';
  }
}

/// Replaced in widget tests with a fake so the sheet never touches the
/// platform picker.
final Provider<PhotoSource> photoSourceProvider = Provider<PhotoSource>(
  (Ref ref) => ImagePickerPhotoSource(),
);
